<template><el-dialog v-model="open" title="CSV 导入" width="720px"><el-upload drag :auto-upload="false" accept=".csv,text/csv" :limit="1" :on-change="read"><el-icon size="42"><UploadFilled/></el-icon><div>拖入 CSV 文件，或点击选择</div></el-upload><el-alert v-if="rows.length" class="preview" :title="`已解析 ${rows.length} 行，提交前请确认字段映射`" type="success" :closable="false"/><el-table v-if="rows.length" :data="rows.slice(0,5)" max-height="260"><el-table-column v-for="h in headers" :key="h" :prop="h" :label="h" min-width="120"/></el-table><template #footer><el-button @click="open=false">取消</el-button><el-button type="primary" :disabled="!rows.length" @click="submit">导入 {{rows.length}} 行</el-button></template></el-dialog></template>
<script setup lang="ts">import {computed,ref} from 'vue';import type {UploadFile} from 'element-plus';import {parseCsv} from '@/utils/csv';const props=defineProps<{modelValue:boolean}>();const emit=defineEmits<{"update:modelValue":[boolean];submit:[Record<string,string>[]]}>();const headers=ref<string[]>([]);const rows=ref<Record<string,string>[]>([]);const open=computed({get:()=>props.modelValue,set:v=>emit('update:modelValue',v)});async function read(file:UploadFile){const text=await file.raw?.text();if(!text)return;const parsed=parseCsv(text);headers.value=parsed.shift()||[];rows.value=parsed.map(r=>Object.fromEntries(headers.value.map((h,i)=>[h,r[i]||''])))}function submit(){emit('submit',rows.value);open.value=false;rows.value=[]}</script>
<style scoped>.preview{margin:16px 0}</style>
